// LocalStorage Key
const STORAGE_KEY = 'cloud_qm_db_v3';

// Service Class
class MockDataService {
  constructor() {
    this.init();
  }

  init() {
    if (!localStorage.getItem(STORAGE_KEY)) {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(initialData));
    }
  }

  getDB() {
    return JSON.parse(localStorage.getItem(STORAGE_KEY) || '{}');
  }

  saveDB(db) {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(db));
  }

  // Generic CRUD
  getAll(collection) {
    const db = this.getDB();
    return db[collection] || [];
  }

  getById(collection, idField, id) {
    const db = this.getDB();
    return (db[collection] || []).find(item => item[idField] === id);
  }

  create(collection, item) {
    const db = this.getDB();
    if (!db[collection]) db[collection] = [];
    db[collection].push(item);
    this.saveDB(db);
    return item;
  }

  update(collection, idField, id, updates) {
    const db = this.getDB();
    const index = (db[collection] || []).findIndex(item => item[idField] === id);
    if (index !== -1) {
      db[collection][index] = { ...db[collection][index], ...updates };
      this.saveDB(db);
      return db[collection][index];
    }
    return null;
  }

  delete(collection, idField, id) {
    const db = this.getDB();
    const index = (db[collection] || []).findIndex(item => item[idField] === id);
    if (index !== -1) {
      db[collection].splice(index, 1);
      this.saveDB(db);
      return true;
    }
    return false;
  }
}

export const dataService = new MockDataService();
